import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2019-10-10 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-10-10 -- Ceph Performance Meeting","date":"2019-10-10T00:00:00.000Z","updated":"2019-10-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能测试","RGW","Docker 镜像"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-10_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-10-10_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-10-10_-_-_Ceph_Performance_Meeting.md"};function o(n,e,s,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><p>[会议时间]</p><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>[所有参会人员姓名]</li></ul><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><ul><li>新的 Pull Requests (PRs) 更新</li><li>内存需求文档更新</li><li>性能测试和测试节点更新</li><li>RGW 崩溃问题</li><li>Docker 镜像发布流程</li></ul><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><p><strong>1. 新的 PRs 更新</strong></p><ul><li>Eric 提交了关于 RGW 动态分片数量的 PR。</li><li>Sage 提交了可能解决缓存抖动问题的 PR。</li><li>Sage 正在研究内存清理问题，避免污染缓存。</li><li>Adams 提交了防止日志损坏的 PR。</li><li>更新了 key foo 测试，修复了之前的问题。</li><li>使用优先级缓存管理器为 MDS 缓存设置内存限制。</li><li>Adam 重写了 shardene 工作，以便进行测试。</li></ul><p><strong>2. 内存需求文档更新</strong></p><ul><li>由于硬盘容量的增加，客户对现有内存需求文档提出了问题。</li><li>讨论了更新文档的必要性，并提出了基于 OSD 类型的推荐方案。</li><li>决定提交更新文档的 PR。</li></ul><p><strong>3. 性能测试和测试节点更新</strong></p><ul><li>Intel 捐赠了新的测试节点，用于性能测试。</li><li>在新节点上进行了单 OSD 性能测试，发现性能显著提升。</li><li>发现使用 4K 金属大小的 RBD 测试比使用 16K 大小更快。</li><li>进行了 RocksDB 调优，优化性能。</li><li>讨论了使用 FIO 对象存储工具进行测试的可能性。</li></ul><p><strong>4. RGW 崩溃问题</strong></p><ul><li>在 Kubernetes 环境中运行 Ceph 时，RGW 出现崩溃问题。</li><li>分析了核心转储文件，发现与已知问题相关。</li><li>讨论了可能的解决方案，包括重启 Pod 和夜间重启。</li></ul><p><strong>5. Docker 镜像发布流程</strong></p><ul><li>讨论了 Docker 镜像的发布流程，以及如何跟踪和修复问题。</li><li>决定联系 Ken 获取更多信息。</li></ul><h4 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h4><ul><li>参会人员将更新文档的 PR。</li><li>参会人员将继续进行性能测试。</li><li>参会人员将调查 RGW 崩溃问题。</li><li>参会人员将与 Ken 联系，了解 Docker 镜像的发布流程。</li></ul><h4 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h4><p>本次会议讨论了 Ceph 项目的多个方面，包括 PR 更新、文档更新、性能测试、RGW 崩溃问题和 Docker 镜像发布流程。会议确定了行动计划，并分配了任务。</p>',22)])])}const u=l(r,[["render",o]]);export{p as __pageData,u as default};
